// sdkUpdate patches the supplied resource in the backend AWS service API and
// returns a new resource with updated fields.
func (rm *resourceManager) sdkUpdate(
	ctx context.Context,
	desired *resource,
	latest *resource,
	delta *ackcompare.Delta,
) (updated *resource, err error) {
	rlog := ackrtlog.FromContext(ctx)
	exit := rlog.Trace("rm.sdkUpdate")
	defer func() {
		exit(err)
	}()
	if delta.DifferentAt("Spec.Tags") {
		err := syncTags(
			ctx, rm.sdkapi, rm.metrics,
			string(*latest.ko.Status.ACKResourceMetadata.ARN),
			aws.ToStringMap(desired.ko.Spec.Tags), aws.ToStringMap(latest.ko.Spec.Tags),
		)
		if err != nil {
			return nil, err
		}
	}
	if !delta.DifferentExcept("Spec.Tags") {
		return desired, nil
	}
	if latest.ko.Status.Status != nil {
		if !ackutil.InStrings(*latest.ko.Status.Status, []string{"READY"}) {
			return nil, ackrequeue.NeededAfter(
				fmt.Errorf("resource is in %s state, cannot be updated",
					*latest.ko.Status.Status),
				time.Duration(30)*time.Second,
			)
		}
	}

	input, err := rm.newUpdateRequestPayload(ctx, desired, delta)
	if err != nil {
		return nil, err
	}
	// The pinned SDK models only the ARN. UpdateAgentRuntime replaces the
	// provider configuration, so an ARN-only update resets an existing
	// PRIVILEGED runtime to STANDARD even when its ARN stays the same.
	// https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/runtime-instances-privilege-mode.html
	//
	// Carry the existing attachment through other updates when the spec omits it.
	observedProvider := latest.ko.Spec.CapacityProviderConfiguration
	if input.CapacityProviderConfiguration == nil && observedProvider != nil && observedProvider.CapacityProviderARN != nil {
		input.CapacityProviderConfiguration = &svcsdktypes.CapacityProviderConfiguration{
			CapacityProviderArn: observedProvider.CapacityProviderARN,
		}
	}

	var resp *svcsdk.UpdateAgentRuntimeOutput
	_ = resp
	resp, err = rm.sdkapi.UpdateAgentRuntime(ctx, input)
	rm.metrics.RecordAPICall("UPDATE", "UpdateAgentRuntime", err)
	if err != nil {
		return nil, err
	}
	// Merge in the information we read from the API call above to the copy of
	// the original Kubernetes object we passed to the function
	ko := desired.ko.DeepCopy()

	if ko.Status.ACKResourceMetadata == nil {
		ko.Status.ACKResourceMetadata = &ackv1alpha1.ResourceMetadata{}
	}
	if resp.AgentRuntimeArn != nil {
		arn := ackv1alpha1.AWSResourceName(*resp.AgentRuntimeArn)
		ko.Status.ACKResourceMetadata.ARN = &arn
	}
	if resp.AgentRuntimeId != nil {
		ko.Status.AgentRuntimeID = resp.AgentRuntimeId
	} else {
		ko.Status.AgentRuntimeID = nil
	}
	if resp.AgentRuntimeVersion != nil {
		ko.Status.AgentRuntimeVersion = resp.AgentRuntimeVersion
	} else {
		ko.Status.AgentRuntimeVersion = nil
	}
	if resp.CreatedAt != nil {
		ko.Status.CreatedAt = &metav1.Time{*resp.CreatedAt}
	} else {
		ko.Status.CreatedAt = nil
	}
	if resp.Status != "" {
		ko.Status.Status = aws.String(string(resp.Status))
	} else {
		ko.Status.Status = nil
	}
	if resp.WorkloadIdentityDetails != nil {
		f6 := &svcapitypes.WorkloadIdentityDetails{}
		if resp.WorkloadIdentityDetails.WorkloadIdentityArn != nil {
			f6.WorkloadIdentityARN = resp.WorkloadIdentityDetails.WorkloadIdentityArn
		}
		ko.Status.WorkloadIdentityDetails = f6
	} else {
		ko.Status.WorkloadIdentityDetails = nil
	}

	rm.setStatusDefaults(ko)
	return &resource{ko}, nil
}

